    private static Geometry Make(string data)
    {
        // Path data is in a 1000-unit box; scale to the unit box.
        var geometry = Geometry.Parse(data).Clone();
        geometry.Transform = new ScaleTransform(0.001, 0.001);
        var flat = geometry.GetFlattenedPathGeometry();
        flat.FillRule = FillRule.EvenOdd;
        flat.Freeze();
        return flat;
    }
}
